    "color-inversion-markdown-code-19": "#include <cuda_runtime.h>\n\n__global__ void invert_kernel(\n    unsigned char* image,\n    int width,\n    int height\n) {\n    int id = blockIdx.x * blockDim.x + threadIdx.x;\n    int total = width * height * 4;\n\n    if (id < total && id % 4 != 3) {\n        image[id] = 255 - image[id];\n    }\n}\n\n// image is a device pointer (i.e. pointer to memory on the GPU)\nextern \"C\" void solve(\n    unsigned char* image,\n    int width,\n    int height\n) {\n    int threadsPerBlock = 256;\n    int total = width * height * 4;\n    int blocksPerGrid =\n        (total + threadsPerBlock - 1) / threadsPerBlock;\n\n    invert_kernel<<<blocksPerGrid, threadsPerBlock>>>(image, width, height);\n    cudaDeviceSynchronize();\n}"
